+// Sales-tax rates by region, in basis points (1 bp = 0.01%).
+export const TAX_BPS = Object.freeze({ "US-CA": 725, "US-NY": 400, "US-OR": 0, "DE": 1900, "GB": 2000 });
+
+export function taxCents(amountCents, region) {
+  const bps = TAX_BPS[region];
+  if (bps === undefined) throw new RangeError(`unknown tax region: ${region}`);
+  return Math.round((amountCents * bps) / 10000);
+}

